Here is the commit message:
crypto: rsa-pkcs1pad - fix buffer overread in
 pkcs1pad_verify_complete()

Before checking whether the expected digest_info is present, we need to
check that there are enough bytes remaining.

Fixes: a49de377e051 ("crypto: Add hash param to pkcs1pad")
Cc: <stable@vger.kernel.org> # v4.6+
Cc: Tadeusz Struk <tadeusz.struk@linaro.org>
Signed-off-by: Eric Biggers <ebiggers@google.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug was caused by a lack of validation to ensure that there were enough bytes remaining in the output buffer before accessing the `digest_info` data. This oversight could lead to a buffer overread, where the function attempts to read beyond the allocated memory, potentially causing undefined behavior or security vulnerabilities.

Here is the patch:

 static int pkcs1pad_verify_complete(struct akcipher_request *req, int err)
 {
 	struct crypto_akcipher *tfm = crypto_akcipher_reqtfm(req);
 	struct pkcs1pad_ctx *ctx = akcipher_tfm_ctx(tfm);
 	struct pkcs1pad_request *req_ctx = akcipher_request_ctx(req);
 	struct akcipher_instance *inst = akcipher_alg_instance(tfm);
 	struct pkcs1pad_inst_ctx *ictx = akcipher_instance_ctx(inst);
 	const struct rsa_asn1_template *digest_info = ictx->digest_info;
 	unsigned int dst_len;
 	unsigned int pos;
 	u8 *out_buf;

 	if (err)
 		goto done;

 	err = -EINVAL;
 	dst_len = req_ctx->child_req.dst_len;
 	if (dst_len < ctx->key_size - 1)
 		goto done;

 	out_buf = req_ctx->out_buf;
 	if (dst_len == ctx->key_size) {
 		if (out_buf[0] != 0x00)
 			/* Decrypted value had no leading 0 byte */
 			goto done;

 		dst_len--;
 		out_buf++;
 	}

 	err = -EBADMSG;
 	if (out_buf[0] != 0x01)
 		goto done;

 	for (pos = 1; pos < dst_len; pos++)
 		if (out_buf[pos] != 0xff)
 			break;

 	if (pos < 9 || pos == dst_len || out_buf[pos] != 0x00)
 		goto done;
 	pos++;

 	if (digest_info) {
+		if (digest_info->size > dst_len - pos)
+			goto done;
 		if (crypto_memneq(out_buf + pos, digest_info->data,
 				  digest_info->size))
 			goto done;

 		pos += digest_info->size;
 	}

 	err = 0;

 	if (req->dst_len != dst_len - pos) {
 		err = -EKEYREJECTED;
 		req->dst_len = dst_len - pos;
 		goto done;
 	}
 	/* Extract appended digest. */
 	sg_pcopy_to_buffer(req->src,
 			   sg_nents_for_len(req->src,
 					    req->src_len + req->dst_len),
 			   req_ctx->out_buf + ctx->key_size,
 			   req->dst_len, req->src_len);
 	/* Do the actual verification step. */
 	if (memcmp(req_ctx->out_buf + ctx->key_size, out_buf + pos,
 		   req->dst_len) != 0)
 		err = -EKEYREJECTED;
 done:
 	kfree_sensitive(req_ctx->out_buf);

 	return err;
 }



